// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 1200, 360);

var state = { n: 6, single: false, step: 0 };
var blue = '#2aa0d8';
var pale = '#c9e3ef';
var axis = '#222222';

var demoSteps = [
  {
    title: 'The target area',
    narration: 'Panel (a) shows the exact region whose area is being approximated: the area under the curve from a to b. The shaded shape is not made of rectangles yet; it is the quantity the integral will define.',
    state: { viewMode: 'Three-panel comparison', rectangleCount: 6 }
  },
  {
    title: 'Coarse inscribed rectangles',
    narration: 'With only a few wide rectangles, the approximation captures some of the area but leaves noticeable gaps under the curve. The displayed Riemann sum is the total area of these rectangles.',
    state: { viewMode: 'Single animated refinement', rectangleCount: 6 }
  },
  {
    title: 'Refining the approximation',
    narration: 'As n increases, the rectangles become thinner and fit the curve more closely. The missing gaps shrink, so the rectangular sum moves closer to the true shaded area.',
    state: { viewMode: 'Single animated refinement', rectangleCount: 24 }
  },
  {
    title: 'The limiting idea',
    narration: 'The definite integral is the limiting value approached by these sums as n grows without bound. The rectangles are not the final object; they are the method for defining the area.',
    state: { viewMode: 'Single animated refinement', rectangleCount: 40 }
  }
];

function f(u) {
  return 0.44 +
    0.23 * Math.sin(2 * Math.PI * (0.95 * u) + 0.2) +
    0.16 * u +
    0.08 * Math.sin(4 * Math.PI * u - 0.9);
}

function integrateTrue() {
  var n = 800, h = 1 / n, s = f(0) + f(1);
  for (var i = 1; i < n; i++) s += f(i * h) * (i % 2 ? 4 : 2);
  return s * h / 3;
}

function minOnInterval(a, b) {
  var m = Infinity;
  for (var k = 0; k <= 14; k++) {
    var u = a + (b - a) * k / 14;
    m = Math.min(m, f(u));
  }
  return m;
}

function riemannSum(n) {
  var dx = 1 / n, s = 0;
  for (var i = 0; i < n; i++) s += minOnInterval(i * dx, (i + 1) * dx) * dx;
  return s;
}

function textLabel(parent, str, x, y, size, italic, anchor) {
  return parent.text(str).font({
    family: 'Times New Roman, Georgia, serif',
    size: size,
    style: italic ? 'italic' : 'normal',
    anchor: anchor || 'middle'
  }).fill(axis).move(x, y);
}

function addAxes(g, cfg) {
  var x0 = cfg.x0, y0 = cfg.y0, xEnd = cfg.xEnd, yTop = cfg.yTop;
  g.line(x0 - 30, y0, xEnd, y0).stroke({ color: axis, width: 1.5 });
  g.polygon([[xEnd, y0], [xEnd - 13, y0 - 7], [xEnd - 13, y0 + 7]]).fill(axis);
  g.line(x0, y0 + 30, x0, yTop).stroke({ color: axis, width: 1.5 });
  g.polygon([[x0, yTop], [x0 - 7, yTop + 13], [x0 + 7, yTop + 13]]).fill(axis);
  textLabel(g, 'x', xEnd - 12, y0 - 31, 22, true, 'middle');
  textLabel(g, 'y', x0 + 16, yTop - 8, 22, true, 'middle');
  textLabel(g, 'a', cfg.a, y0 + 10, 24, true, 'middle');
  textLabel(g, 'b', cfg.b, y0 + 10, 24, true, 'middle');
}

function yFromU(cfg, u) {
  return cfg.y0 - f(u) * cfg.scaleY;
}

function pathCurve(cfg, u0, u1, samples) {
  var d = '';
  for (var i = 0; i <= samples; i++) {
    var u = u0 + (u1 - u0) * i / samples;
    var x = cfg.a + (cfg.b - cfg.a) * u;
    var y = yFromU(cfg, u);
    d += (i ? 'L' : 'M') + x.toFixed(2) + ' ' + y.toFixed(2);
  }
  return d;
}

function areaPath(cfg) {
  var d = 'M' + cfg.a + ' ' + cfg.y0 + 'L';
  for (var i = 0; i <= 140; i++) {
    var u = i / 140;
    var x = cfg.a + (cfg.b - cfg.a) * u;
    d += x.toFixed(2) + ' ' + yFromU(cfg, u).toFixed(2) + (i < 140 ? 'L' : '');
  }
  d += 'L' + cfg.b + ' ' + cfg.y0 + 'Z';
  return d;
}

function drawArea(g, cfg, opacity) {
  return g.path(areaPath(cfg)).fill({ color: pale, opacity: opacity == null ? 1 : opacity }).stroke('none')
    .on('mousemove', function (e) { showTooltip('The true area under the curve on [a, b].', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Target area', 'This shaded region is the area the definite integral represents. Rectangles are used to define and approximate this area.');
    }).css('cursor', 'pointer');
}

function drawCurve(g, cfg) {
  return g.path(pathCurve(cfg, -0.06, 1.11, 180)).fill('none')
    .stroke({ color: blue, width: 4, linecap: 'round', linejoin: 'round' })
    .on('mousemove', function (e) { showTooltip('Smooth function y = f(x).', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The curve', 'The curve gives the height of the region. Each rectangle must stay below it on its subinterval to be inscribed.');
    }).css('cursor', 'pointer');
}

function drawBoundaryLines(g, cfg) {
  g.line(cfg.a, cfg.y0, cfg.a, yFromU(cfg, 0)).stroke({ color: axis, width: 1.3 });
  g.line(cfg.b, cfg.y0, cfg.b, yFromU(cfg, 1)).stroke({ color: axis, width: 1.3 });
}

function drawRectangles(g, cfg, n, opacity) {
  var dx = (cfg.b - cfg.a) / n;
  var group = g.group();
  for (var i = 0; i < n; i++) {
    var u0 = i / n, u1 = (i + 1) / n;
    var h = minOnInterval(u0, u1);
    var x = cfg.a + i * dx;
    var y = cfg.y0 - h * cfg.scaleY;
    group.rect(dx, cfg.y0 - y)
      .move(x, y)
      .fill({ color: pale, opacity: opacity == null ? 1 : opacity })
      .stroke({ color: axis, width: n > 25 ? 0.85 : 1.15 })
      .on('mousemove', function (e) { showTooltip('One inscribed rectangle: area = height × Δx.', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Inscribed rectangle', 'Its height is chosen so the rectangle does not rise above the curve. Adding all such rectangle areas gives the inscribed Riemann sum Aₙ.');
      })
      .css('cursor', 'pointer');
  }
  return group;
}

function panelLabel(g, s, x, y) {
  textLabel(g, s, x, y, 25, true, 'middle');
}

function renderThreePanels() {
  draw.clear();
  var panels = [
    { ox: 20, label: '(a)', mode: 'area' },
    { ox: 420, label: '(b)', mode: 'coarse' },
    { ox: 820, label: '(c)', mode: 'fine' }
  ];
  panels.forEach(function (p) {
    var g = draw.group();
    var cfg = {
      x0: p.ox + 22,
      y0: 270,
      xEnd: p.ox + 365,
      yTop: 24,
      a: p.ox + 48,
      b: p.ox + 315,
      scaleY: 205
    };
    addAxes(g, cfg);
    if (p.mode === 'area') {
      drawArea(g, cfg, 1);
      drawBoundaryLines(g, cfg);
    } else if (p.mode === 'coarse') {
      drawRectangles(g, cfg, 6, 1);
    } else {
      drawRectangles(g, cfg, 28, 1);
    }
    drawCurve(g, cfg);
    panelLabel(g, p.label, p.ox + 200, 318);
  });
  updateReadout();
}

function renderSingle() {
  draw.clear();
  var g = draw.group();
  var cfg = {
    x0: 84,
    y0: 292,
    xEnd: 1090,
    yTop: 25,
    a: 160,
    b: 990,
    scaleY: 235
  };
  addAxes(g, cfg);
  drawArea(g, cfg, 0.26);
  drawRectangles(g, cfg, state.n, 0.92);
  drawCurve(g, cfg);
  drawBoundaryLines(g, cfg);

  var sum = riemannSum(state.n);
  var trueA = integrateTrue();
  var box = g.group();
  box.rect(310, 64).move(122, 38).fill({ color: '#ffffff', opacity: 0.86 }).stroke({ color: '#d7d7d7', width: 0.8 });
  box.text('Aₙ = Σ rectangle areas ≈ ' + sum.toFixed(3))
    .font({ family: 'Georgia, Times New Roman, serif', size: 19 })
    .fill(axis).move(137, 48);
  box.text('n = ' + state.n + ',   Δx = (b − a) / n' + '     true area ≈ ' + trueA.toFixed(3))
    .font({ family: 'Georgia, Times New Roman, serif', size: 15 })
    .fill(axis).move(137, 76);

  box.on('mousemove', function (e) {
    showTooltip('As n grows, Aₙ approaches the definite integral.', e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    showPopup('Riemann sum', 'Aₙ is the sum of all rectangle areas. The definite integral is the limiting value approached by these sums as Δx tends to zero.');
  }).css('cursor', 'pointer');

  updateReadout();
}

function updateReadout() {
  var el = document.getElementById('sumReadout');
  if (!el) return;
  var sum = riemannSum(state.n);
  el.textContent = 'Aₙ ≈ ' + sum.toFixed(3) + ' · Δx = 1/' + state.n;
}

function render() {
  if (state.single) renderSingle();
  else renderThreePanels();
}

function update_rectangleCount(v) {
  state.n = Math.max(2, Math.min(40, Math.round(v)));
  render();
}

function toggle_viewMode(on) {
  state.single = !!on;
  render();
}

function applyStep(i) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[state.step];
  state.single = step.state.viewMode === 'Single animated refinement';
  state.n = step.state.rectangleCount;

  var nInput = document.getElementById('rectangleCountInput');
  var nVal = document.getElementById('rectangleCountVal');
  var modeInput = document.getElementById('viewModeInput');
  if (nInput) nInput.value = state.n;
  if (nVal) nVal.value = state.n;
  if (modeInput) modeInput.checked = state.single;

  var narration = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narration) narration.textContent = step.narration;
  if (label) label.textContent = (state.step + 1) + '/4: ' + step.title;

  render();
}

function prevStep() {
  applyStep(state.step - 1);
}

function nextStep() {
  applyStep(state.step + 1);
}

window.update_rectangleCount = update_rectangleCount;
window.toggle_viewMode = toggle_viewMode;
window.prevStep = prevStep;
window.nextStep = nextStep;

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

