// @FIGURE_CODE_BEGIN
document.documentElement.style.setProperty('--figure-canvas-padding', '6px');

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.attr({ preserveAspectRatio: 'xMidYMid meet' });

var state = { n: 6, single: false, step: 0 };
var blue = '#2aa0d8';
var pale = '#c9e3ef';
var axis = '#222222';
var rectStroke = '#2b2b2b';
var baseW = 1200;
var baseH = 520;
var resizeTimer = 0;

var demoSteps = [
  {
    title: 'The target area',
    narration: 'Panel (a) shows the exact region whose area is being approximated: the area under the curve from a to b. The shaded shape is not made of rectangles yet; it is the quantity the integral will define.',
    state: { viewMode: 'Three-panel comparison', rectangleCount: 6 }
  },
  {
    title: 'Coarse inscribed rectangles',
    narration: 'With only a few wide rectangles, the approximation captures some of the area but leaves noticeable gaps under the curve. The displayed Riemann sum is the total area of these rectangles.',
    state: { viewMode: 'Single animated refinement', rectangleCount: 6 }
  },
  {
    title: 'Refining the approximation',
    narration: 'As n increases, the rectangles become thinner and fit the curve more closely. The missing gaps shrink, so the rectangular sum moves closer to the true shaded area.',
    state: { viewMode: 'Single animated refinement', rectangleCount: 24 }
  },
  {
    title: 'The limiting idea',
    narration: 'The definite integral is the limiting value approached by these sums as n grows without bound. The rectangles are not the final object; they are the method for defining the area.',
    state: { viewMode: 'Single animated refinement', rectangleCount: 40 }
  }
];

var curvePts = [
  { u: -0.06, y: 0.34, m: 2.25 },
  { u: 0.00, y: 0.47, m: 2.05 },
  { u: 0.16, y: 0.78, m: 1.05 },
  { u: 0.29, y: 0.86, m: 0.00 },
  { u: 0.45, y: 0.75, m: -1.22 },
  { u: 0.63, y: 0.48, m: -1.45 },
  { u: 0.74, y: 0.39, m: 0.00 },
  { u: 0.88, y: 0.43, m: 0.50 },
  { u: 1.00, y: 0.54, m: 1.35 },
  { u: 1.10, y: 0.82, m: 3.15 }
];

function clamp(x, a, b) {
  return Math.max(a, Math.min(b, x));
}

function currentViewboxHeight() {
  var c = document.getElementById('container');
  var w = Math.max(1, c.clientWidth || 900);
  var h = Math.max(1, c.clientHeight || 520);
  var target = baseW / (w / h);
  return clamp(target, 455, 640);
}

function hermite(p0, p1, u) {
  var t = (u - p0.u) / (p1.u - p0.u);
  var h00 = 2 * t * t * t - 3 * t * t + 1;
  var h10 = t * t * t - 2 * t * t + t;
  var h01 = -2 * t * t * t + 3 * t * t;
  var h11 = t * t * t - t * t;
  var du = p1.u - p0.u;
  return h00 * p0.y + h10 * du * p0.m + h01 * p1.y + h11 * du * p1.m;
}

function f(u) {
  if (u <= curvePts[0].u) return curvePts[0].y + curvePts[0].m * (u - curvePts[0].u);
  if (u >= curvePts[curvePts.length - 1].u) {
    var q = curvePts[curvePts.length - 1];
    return q.y + q.m * (u - q.u);
  }
  for (var i = 0; i < curvePts.length - 1; i++) {
    if (u >= curvePts[i].u && u <= curvePts[i + 1].u) return hermite(curvePts[i], curvePts[i + 1], u);
  }
  return 0;
}

function integrateTrue() {
  var n = 1000;
  if (n % 2) n++;
  var h = 1 / n;
  var s = f(0) + f(1);
  for (var i = 1; i < n; i++) s += f(i * h) * (i % 2 ? 4 : 2);
  return s * h / 3;
}

function minOnInterval(a, b) {
  var m = Infinity;
  for (var k = 0; k <= 30; k++) {
    var u = a + (b - a) * k / 30;
    m = Math.min(m, f(u));
  }
  return m;
}

function riemannSum(n) {
  var dx = 1 / n;
  var s = 0;
  for (var i = 0; i < n; i++) s += minOnInterval(i * dx, (i + 1) * dx) * dx;
  return s;
}

function textLabel(parent, str, x, y, size, italic, anchor) {
  return parent.text(str).font({
    family: 'Times New Roman, Georgia, serif',
    size: size,
    style: italic ? 'italic' : 'normal',
    anchor: anchor || 'middle'
  }).fill(axis).attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': Math.max(2, size * 0.10),
    'stroke-linejoin': 'round'
  }).move(x, y);
}

function yFromU(cfg, u) {
  return cfg.y0 - f(u) * cfg.scaleY;
}

function pathCurve(cfg, u0, u1, samples) {
  var d = '';
  for (var i = 0; i <= samples; i++) {
    var u = u0 + (u1 - u0) * i / samples;
    var x = cfg.a + (cfg.b - cfg.a) * u;
    var y = yFromU(cfg, u);
    d += (i ? 'L' : 'M') + x.toFixed(2) + ' ' + y.toFixed(2);
  }
  return d;
}

function areaPath(cfg) {
  var d = 'M' + cfg.a + ' ' + cfg.y0 + 'L';
  for (var i = 0; i <= 180; i++) {
    var u = i / 180;
    var x = cfg.a + (cfg.b - cfg.a) * u;
    d += x.toFixed(2) + ' ' + yFromU(cfg, u).toFixed(2) + (i < 180 ? 'L' : '');
  }
  d += 'L' + cfg.b + ' ' + cfg.y0 + 'Z';
  return d;
}

function addAxesGeometry(g, cfg) {
  var aw = cfg.arrow || 14;
  var axisW = cfg.axisW || 1.8;
  g.line(cfg.x0 - cfg.leftStub, cfg.y0, cfg.xEnd, cfg.y0).stroke({ color: axis, width: axisW });
  g.polygon([[cfg.xEnd, cfg.y0], [cfg.xEnd - aw, cfg.y0 - aw * 0.52], [cfg.xEnd - aw, cfg.y0 + aw * 0.52]]).fill(axis);
  g.line(cfg.x0, cfg.y0 + cfg.downStub, cfg.x0, cfg.yTop).stroke({ color: axis, width: axisW });
  g.polygon([[cfg.x0, cfg.yTop], [cfg.x0 - aw * 0.52, cfg.yTop + aw], [cfg.x0 + aw * 0.52, cfg.yTop + aw]]).fill(axis);
}

function addAxisLabels(g, cfg) {
  textLabel(g, 'x', cfg.xEnd - cfg.labelSize * 0.85, cfg.y0 - cfg.labelSize * 1.15, cfg.labelSize, true, 'middle');
  textLabel(g, 'y', cfg.x0 + cfg.labelSize * 0.55, cfg.yTop - cfg.labelSize * 0.15, cfg.labelSize, true, 'middle');
  textLabel(g, 'a', cfg.a, cfg.y0 + cfg.endpointSize * 0.15, cfg.endpointSize, true, 'middle');
  textLabel(g, 'b', cfg.b, cfg.y0 + cfg.endpointSize * 0.15, cfg.endpointSize, true, 'middle');
}

function drawArea(g, cfg, opacity) {
  return g.path(areaPath(cfg)).fill({ color: pale, opacity: opacity == null ? 1 : opacity }).stroke('none')
    .on('mousemove', function (e) { showTooltip('The true area under the curve on [a, b].', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Target area', 'This shaded region is the area the definite integral represents. Rectangles are used to define and approximate this area.');
    }).css('cursor', 'pointer');
}

function drawCurve(g, cfg) {
  return g.path(pathCurve(cfg, -0.06, 1.11, 230)).fill('none')
    .stroke({ color: blue, width: cfg.curveW || 5, linecap: 'round', linejoin: 'round' })
    .on('mousemove', function (e) { showTooltip('Smooth function y = f(x).', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The curve', 'The curve gives the height of the region. Inscribed rectangles use heights that stay below this curve on each subinterval.');
    }).css('cursor', 'pointer');
}

function drawBoundaryLines(g, cfg) {
  g.line(cfg.a, cfg.y0, cfg.a, yFromU(cfg, 0)).stroke({ color: axis, width: cfg.boundaryW || 1.8 });
  g.line(cfg.b, cfg.y0, cfg.b, yFromU(cfg, 1)).stroke({ color: axis, width: cfg.boundaryW || 1.8 });
}

function drawRectangles(g, cfg, n, opacity) {
  var dx = (cfg.b - cfg.a) / n;
  var group = g.group();
  var strokeW = n > 25 ? Math.max(0.75, cfg.rectW * 0.72) : cfg.rectW;
  for (var i = 0; i < n; i++) {
    var u0 = i / n;
    var u1 = (i + 1) / n;
    var h = minOnInterval(u0, u1);
    var x = cfg.a + i * dx;
    var y = cfg.y0 - h * cfg.scaleY;
    group.rect(dx, cfg.y0 - y)
      .move(x, y)
      .fill({ color: pale, opacity: opacity == null ? 1 : opacity })
      .stroke({ color: rectStroke, width: strokeW })
      .on('mousemove', function (e) { showTooltip('One inscribed rectangle: area = height × Δx.', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Inscribed rectangle', 'Its height is chosen so the rectangle does not rise above the curve anywhere on that subinterval. Adding all rectangle areas gives the inscribed Riemann sum Aₙ.');
      })
      .css('cursor', 'pointer');
  }
  return group;
}

function panelCfg(ox, H) {
  var y0 = H * 0.725;
  var yTop = H * 0.055;
  return {
    x0: ox + 54,
    y0: y0,
    xEnd: ox + 388,
    yTop: yTop,
    leftStub: 44,
    downStub: H * 0.105,
    a: ox + 102,
    b: ox + 334,
    scaleY: (y0 - yTop - H * 0.075) / 0.90,
    arrow: H * 0.030,
    axisW: Math.max(1.7, H * 0.0038),
    curveW: Math.max(4.5, H * 0.0095),
    rectW: Math.max(1.15, H * 0.003),
    boundaryW: Math.max(1.55, H * 0.0032),
    labelSize: clamp(H * 0.056, 25, 35),
    endpointSize: clamp(H * 0.064, 29, 42),
    panelSize: clamp(H * 0.067, 30, 44),
    panelY: H * 0.845
  };
}

function panelLabel(g, s, cfg, cx) {
  textLabel(g, s, cx, cfg.panelY, cfg.panelSize, true, 'middle');
}

function renderThreePanels() {
  draw.clear();
  baseH = currentViewboxHeight();
  draw.viewbox(0, 0, baseW, baseH);

  var panels = [
    { ox: 0, label: '(a)', mode: 'area' },
    { ox: 400, label: '(b)', mode: 'coarse' },
    { ox: 800, label: '(c)', mode: 'fine' }
  ];

  panels.forEach(function (p) {
    var g = draw.group();
    var cfg = panelCfg(p.ox, baseH);

    addAxesGeometry(g, cfg);
    if (p.mode === 'area') {
      drawArea(g, cfg, 1);
      drawBoundaryLines(g, cfg);
    } else if (p.mode === 'coarse') {
      drawRectangles(g, cfg, 6, 1);
    } else {
      drawRectangles(g, cfg, 30, 1);
    }
    drawCurve(g, cfg);
    addAxisLabels(g, cfg);
    panelLabel(g, p.label, cfg, p.ox + 200);
  });

  updateReadout();
}

function singleCfg(H) {
  var y0 = H * 0.760;
  var yTop = H * 0.055;
  return {
    x0: 92,
    y0: y0,
    xEnd: 1136,
    yTop: yTop,
    leftStub: 70,
    downStub: H * 0.105,
    a: 178,
    b: 1034,
    scaleY: (y0 - yTop - H * 0.08) / 0.90,
    arrow: H * 0.030,
    axisW: Math.max(2, H * 0.0039),
    curveW: Math.max(5.5, H * 0.0105),
    rectW: Math.max(1.15, H * 0.0031),
    boundaryW: Math.max(1.7, H * 0.0033),
    labelSize: clamp(H * 0.052, 27, 36),
    endpointSize: clamp(H * 0.062, 32, 44)
  };
}

function renderSingle() {
  draw.clear();
  baseH = currentViewboxHeight();
  draw.viewbox(0, 0, baseW, baseH);

  var g = draw.group();
  var cfg = singleCfg(baseH);

  addAxesGeometry(g, cfg);
  drawArea(g, cfg, 0.25);
  drawRectangles(g, cfg, state.n, 0.94);
  drawCurve(g, cfg);
  drawBoundaryLines(g, cfg);
  addAxisLabels(g, cfg);

  var sum = riemannSum(state.n);
  var trueA = integrateTrue();
  var boxW = 380;
  var boxH = 74;
  var boxX = 132;
  var boxY = Math.max(22, baseH * 0.075);
  var box = g.group();
  box.rect(boxW, boxH).move(boxX, boxY).fill({ color: '#ffffff', opacity: 0.88 }).stroke({ color: '#d7d7d7', width: 0.9 });
  box.text('Aₙ = Σ rectangle areas ≈ ' + sum.toFixed(3))
    .font({ family: 'Georgia, Times New Roman, serif', size: clamp(baseH * 0.032, 18, 24) })
    .fill(axis).move(boxX + 18, boxY + 12);
  box.text('n = ' + state.n + ',   Δx = (b − a) / n     true area ≈ ' + trueA.toFixed(3))
    .font({ family: 'Georgia, Times New Roman, serif', size: clamp(baseH * 0.024, 14, 18) })
    .fill(axis).move(boxX + 18, boxY + 43);

  box.on('mousemove', function (e) {
    showTooltip('As n grows, Aₙ approaches the definite integral.', e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    showPopup('Riemann sum', 'Aₙ is the sum of all rectangle areas. The definite integral is the limiting value approached by these sums as Δx tends to zero.');
  }).css('cursor', 'pointer');

  updateReadout();
}

function updateReadout() {
  var el = document.getElementById('sumReadout');
  if (!el) return;
  var sum = riemannSum(state.n);
  var trueA = integrateTrue();
  el.textContent = 'Aₙ ≈ ' + sum.toFixed(3) + ' · Δx = 1/' + state.n + '  →  ∫ ≈ ' + trueA.toFixed(3);
}

function render() {
  if (state.single) renderSingle();
  else renderThreePanels();
}

function update_rectangleCount(v) {
  state.n = Math.max(2, Math.min(40, Math.round(v)));
  render();
}

function toggle_viewMode(on) {
  state.single = !!on;
  render();
}

function applyStep(i) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[state.step];
  state.single = step.state.viewMode === 'Single animated refinement';
  state.n = step.state.rectangleCount;

  var nInput = document.getElementById('rectangleCountInput');
  var nVal = document.getElementById('rectangleCountVal');
  var modeInput = document.getElementById('viewModeInput');
  if (nInput) nInput.value = state.n;
  if (nVal) nVal.value = state.n;
  if (modeInput) modeInput.checked = state.single;

  var narration = document.getElementById('demoNarration');
  var label = document.getElementById('stepLabel');
  if (narration) narration.textContent = step.narration;
  if (label) label.textContent = (state.step + 1) + '/4: ' + step.title;

  render();
}

function prevStep() {
  applyStep(state.step - 1);
}

function nextStep() {
  applyStep(state.step + 1);
}

document.addEventListener('fig-resize', function () {
  clearTimeout(resizeTimer);
  resizeTimer = setTimeout(render, 20);
});

window.update_rectangleCount = update_rectangleCount;
window.toggle_viewMode = toggle_viewMode;
window.prevStep = prevStep;
window.nextStep = nextStep;

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

