  return m;
}

function riemannSum(n) {
  var dx = 1 / n;
  var s = 0;
  for (var i = 0; i < n; i++) s += minOnInterval(i * dx, (i + 1) * dx) * dx;
  return s;
}

function label(parent, str, x, y, size, italic, anchor) {
  var t = parent.text(str).font({
    family: 'Times New Roman, Georgia, serif',
    size: size,
    style: italic ? 'italic' : 'normal',
    anchor: anchor || 'middle'
  }).fill(axis).attr({
    'paint-order': 'stroke',
    stroke: '#ffffff',
    'stroke-width': Math.max(2, size * 0.09),
    'stroke-linejoin': 'round'
  });
  t.center(x, y);
  return t;
}

function yFromU(cfg, u) {
  return cfg.y0 - f(u) * cfg.scaleY;
}

function pathCurve(cfg, u0, u1, samples) {
  var d = '';
  for (var i = 0; i <= samples; i++) {
    var u = u0 + (u1 - u0) * i / samples;
    var x = cfg.a + (cfg.b - cfg.a) * u;
    var y = yFromU(cfg, u);
    d += (i ? 'L' : 'M') + x.toFixed(2) + ' ' + y.toFixed(2);
  }
  return d;
}

function areaPath(cfg) {
  var d = 'M' + cfg.a + ' ' + cfg.y0 + 'L';
  for (var i = 0; i <= 180; i++) {
    var u = i / 180;
    d += (cfg.a + (cfg.b - cfg.a) * u).toFixed(2) + ' ' + yFromU(cfg, u).toFixed(2) + (i < 180 ? 'L' : '');
  }
  return d + 'L' + cfg.b + ' ' + cfg.y0 + 'Z';
}

function addAxesGeometry(g, cfg) {
  var aw = cfg.arrow;
  g.line(cfg.x0 - cfg.leftStub, cfg.y0, cfg.xEnd, cfg.y0).stroke({ color: axis, width: cfg.axisW });
  g.polygon([[cfg.xEnd, cfg.y0], [cfg.xEnd - aw, cfg.y0 - aw * 0.50], [cfg.xEnd - aw, cfg.y0 + aw * 0.50]]).fill(axis);
  g.line(cfg.x0, cfg.y0 + cfg.downStub, cfg.x0, cfg.yTop).stroke({ color: axis, width: cfg.axisW });
  g.polygon([[cfg.x0, cfg.yTop], [cfg.x0 - aw * 0.50, cfg.yTop + aw], [cfg.x0 + aw * 0.50, cfg.yTop + aw]]).fill(axis);
}

function addAxisLabels(g, cfg) {
  label(g, 'x', cfg.xEnd - cfg.labelSize * 0.78, cfg.y0 - cfg.labelSize * 0.88, cfg.labelSize, true);
  label(g, 'y', cfg.x0 + cfg.labelSize * 0.72, cfg.yTop + cfg.labelSize * 0.22, cfg.labelSize, true);
  label(g, 'a', cfg.a, cfg.y0 + cfg.endpointSize * 0.78, cfg.endpointSize, true);
  label(g, 'b', cfg.b, cfg.y0 + cfg.endpointSize * 0.78, cfg.endpointSize, true);
}

function drawArea(g, cfg, opacity) {
  return g.path(areaPath(cfg)).fill({ color: pale, opacity: opacity == null ? 1 : opacity }).stroke('none')
    .on('mousemove', function (e) { showTooltip('The target area under the curve on [a, b].', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Target area', 'This shaded region is the area represented by the definite integral. Rectangles give approximations whose limiting value defines that area.');
    }).css('cursor', 'pointer');
}

function drawCurve(g, cfg) {
  return g.path(pathCurve(cfg, -0.06, 1.11, 260)).fill('none')
    .stroke({ color: blue, width: cfg.curveW, linecap: 'round', linejoin: 'round' })
    .on('mousemove', function (e) { showTooltip('Smooth function y = f(x).', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('The curve', 'The curve supplies the height f(x). Inscribed rectangles are chosen so their tops never go above the curve on each subinterval.');
    }).css('cursor', 'pointer');
}

function drawBoundaryLines(g, cfg) {
  g.line(cfg.a, cfg.y0, cfg.a, yFromU(cfg, 0)).stroke({ color: axis, width: cfg.boundaryW });
  g.line(cfg.b, cfg.y0, cfg.b, yFromU(cfg, 1)).stroke({ color: axis, width: cfg.boundaryW });
}

function drawRectangles(g, cfg, n, opacity) {
  var dx = (cfg.b - cfg.a) / n;
  var group = g.group();
  var strokeW = n > 25 ? cfg.rectW * 0.62 : cfg.rectW;
  for (var i = 0; i < n; i++) {
    var u0 = i / n;
    var u1 = (i + 1) / n;
    var h = minOnInterval(u0, u1);
    var x = cfg.a + i * dx;
    var y = cfg.y0 - h * cfg.scaleY;
    group.rect(dx, cfg.y0 - y).move(x, y)
      .fill({ color: pale, opacity: opacity == null ? 1 : opacity })
      .stroke({ color: rectStroke, width: strokeW })
      .on('mousemove', function (e) { showTooltip('One inscribed rectangle: area = height × Δx.', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Inscribed rectangle', 'Its height is the smallest curve height on its subinterval, so it stays below the curve. Adding all such rectangle areas gives the inscribed sum Aₙ.');
      }).css('cursor', 'pointer');
  }
  return group;
}

function panelCfg(ox) {
  return {
    x0: ox + 65,
    y0: 285,
    xEnd: ox + 565,
    yTop: 18,
    leftStub: 42,
    downStub: 48,
    a: ox + 110,
    b: ox + 500,
    scaleY: 272,
    arrow: 16,
    axisW: 2.1,
    curveW: 4.7,
    rectW: 1.45,
    boundaryW: 1.9,
    labelSize: 30,
    endpointSize: 35,
    panelSize: 32,
    panelY: 354
  };
}

function panelLabel(g, s, cfg, cx) {
  label(g, s, cx, cfg.panelY, cfg.panelSize, true);
}

function renderThreePanels() {
  draw.clear();
  draw.viewbox(0, 0, threeW, threeH);

  var panels = [
    { ox: 0, label: '(a)', mode: 'area' },
    { ox: 600, label: '(b)', mode: 'coarse' },
    { ox: 1200, label: '(c)', mode: 'fine' }
  ];

  panels.forEach(function (p) {
    var g = draw.group();
    var cfg = panelCfg(p.ox);

    addAxesGeometry(g, cfg);
    if (p.mode === 'area') {
      drawArea(g, cfg, 1);
      drawBoundaryLines(g, cfg);
    } else if (p.mode === 'coarse') {
      drawRectangles(g, cfg, 6, 1);
    } else {
      drawRectangles(g, cfg, 28, 1);
    }
    drawCurve(g, cfg);
    addAxisLabels(g, cfg);
    panelLabel(g, p.label, cfg, p.ox + 300);
  });

  updateReadout();
}

function singleCfg() {
  return {
    x0: 92,
    y0: 340,
    xEnd: 1140,
    yTop: 28,
    leftStub: 70,
    downStub: 55,
    a: 178,
    b: 1035,
    scaleY: 315,
    arrow: 17,
    axisW: 2.3,
    curveW: 5.6,
    rectW: 1.55,
    boundaryW: 2,
    labelSize: 31,
    endpointSize: 38
  };
}

function renderSingle() {
  draw.clear();
  draw.viewbox(0, 0, singleW, singleH);

  var g = draw.group();
  var cfg = singleCfg();

  addAxesGeometry(g, cfg);
  drawArea(g, cfg, 0.26);
  drawRectangles(g, cfg, state.n, 0.95);
  drawCurve(g, cfg);
  drawBoundaryLines(g, cfg);
  addAxisLabels(g, cfg);

  var sum = riemannSum(state.n);
  var trueA = integrateTrue();
  var box = g.group();
  var boxX = 132;
  var boxY = 28;
  box.rect(430, 72).move(boxX, boxY).fill({ color: '#ffffff', opacity: 0.88 }).stroke({ color: '#d7d7d7', width: 0.9 });
  box.text('Aₙ = Σ rectangle areas ≈ ' + sum.toFixed(3))
    .font({ family: 'Georgia, Times New Roman, serif', size: 22 })
    .fill(axis).move(boxX + 18, boxY + 11);
  box.text('n = ' + state.n + ',   Δx = (b − a) / n      true area ≈ ' + trueA.toFixed(3))
    .font({ family: 'Georgia, Times New Roman, serif', size: 16 })
    .fill(axis).move(boxX + 18, boxY + 43);

  box.on('mousemove', function (e) { showTooltip('As n grows, Aₙ approaches the definite integral.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Riemann sum', 'Aₙ is the sum of all rectangle areas. The definite integral is the limit approached by these sums as Δx tends to zero.');
    }).css('cursor', 'pointer');

  updateReadout();
}

function updateReadout() {
  var el = document.getElementById('sumReadout');
  if (!el) return;
  var sum = riemannSum(state.n);
  var trueA = integrateTrue();
  el.textContent = 'Aₙ ≈ ' + sum.toFixed(3) + ' · Δx = 1/' + state.n + '  →  ∫ ≈ ' + trueA.toFixed(3);
}

function render() {
  if (state.single) renderSingle();
  else renderThreePanels();
}

function update_rectangleCount(v) {
  state.n = Math.max(2, Math.min(40, Math.round(v)));
  render();
}

function toggle_viewMode(on) {
  state.single = !!on;
  render();
}

function applyStep(i) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[state.step];
  state.single = step.state.viewMode === 'Single animated refinement';
  state.n = step.state.rectangleCount;

  var nInput = document.getElementById('rectangleCountInput');
  var nVal = document.getElementById('rectangleCountVal');
  var modeInput = document.getElementById('viewModeInput');
  if (nInput) nInput.value = state.n;
  if (nVal) nVal.value = state.n;
  if (modeInput) modeInput.checked = state.single;

  var narration = document.getElementById('demoNarration');
  var stepLabel = document.getElementById('stepLabel');
  if (narration) narration.textContent = step.narration;
  if (stepLabel) stepLabel.textContent = (state.step + 1) + '/4: ' + step.title;

  render();
}

function prevStep() {
  applyStep(state.step - 1);
}

function nextStep() {
  applyStep(state.step + 1);
}

window.update_rectangleCount = update_rectangleCount;
window.toggle_viewMode = toggle_viewMode;
window.prevStep = prevStep;
window.nextStep = nextStep;

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

